310: # Blob ids for the given repo-relative paths (regular files that exist), computed by
311: # `git hash-object -- <paths>` in batches that respect the Windows command-line
312: # limit. Paths travel as arguments, never via --stdin-paths (see Invoke-GitCapture),
313: # so a path holding a newline needs no special case. A batch that fails is retried
314: # one path at a time; a path that still fails gets 'unreadable'.
315: function New-PathMap {
316:     # Path-keyed maps are ordinal (case-sensitive): a.txt and A.txt are two files on
317:     # a case-sensitive filesystem. A PowerShell @{} would merge them.
318:     return , ([System.Collections.Generic.Dictionary[string, string]]::new([StringComparer]::Ordinal))
319: }
