321: function Get-GitBlobIds {
322:     param([string]$Root, [string[]]$Paths)
323:     $result = New-PathMap
324:     $batches = New-Object System.Collections.Generic.List[object]
325:     $current = New-Object System.Collections.Generic.List[string]
326:     $chars = 0
327:     foreach ($p in $Paths) {
328:         if ($current.Count -gt 0 -and ($chars + $p.Length + 3) -gt 24000) {
329:             $batches.Add($current.ToArray())
330:             $current = New-Object System.Collections.Generic.List[string]
331:             $chars = 0
332:         }
333:         $current.Add($p)
334:         $chars += $p.Length + 3
335:     }
336:     if ($current.Count -gt 0) { $batches.Add($current.ToArray()) }
337:     foreach ($batch in $batches) {
338:         $ids = $null
339:         $run = Invoke-GitCapture -Root $Root -GitArgs (@('hash-object', '--') + $batch)
340:         if ($run -and $run.ExitCode -eq 0) {
341:             $lines = @(($script:Utf8NoBom.GetString($run.Bytes) -split "`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ })
342:             if ($lines.Count -eq $batch.Count) { $ids = $lines }
343:         }
344:         for ($i = 0; $i -lt $batch.Count; $i++) {
345:             if ($ids) { $result[$batch[$i]] = $ids[$i]; continue }
346:             $one = Invoke-GitCapture -Root $Root -GitArgs @('hash-object', '--', $batch[$i])
347:             $id = 'unreadable'
348:             if ($one -and $one.ExitCode -eq 0) {
349:                 $text = $script:Utf8NoBom.GetString($one.Bytes).Trim()
350:                 if ($text) { $id = $text }
351:             }
352:             $result[$batch[$i]] = $id
353:         }
354:     }
355:     return , $result
356: }
