358: # File modes of tracked paths that differ from HEAD, from `git diff --raw -z HEAD`
359: # (worktree against HEAD; with core.filemode=false git takes the executable bit from
360: # the index). Value: '100644' when the mode is unchanged, '100644>100755' when it
361: # changed, '000000>100644' for a path new since HEAD, '100644>000000' for a deletion.
362: function Get-GitModeMap {
363:     param([string]$Root)
364:     $map = New-PathMap
365:     $run = Invoke-GitCapture -Root $Root -GitArgs @('--no-optional-locks', 'diff', '--raw', '-z', '--no-renames', '--no-ext-diff', '--no-abbrev', 'HEAD')
366:     if (-not $run -or $run.ExitCode -ne 0) { return , $map }
367:     $tokens = $script:Utf8NoBom.GetString($run.Bytes).Split([char]0)
368:     $i = 0
369:     while ($i -lt $tokens.Length - 1) {
370:         $meta = $tokens[$i]
371:         if (-not $meta.StartsWith(':')) { $i++; continue }
372:         $path = $tokens[$i + 1]
373:         $i += 2
374:         $parts = $meta.Substring(1).Split(' ')
375:         if ($parts.Length -lt 2) { continue }
376:         $mode = $parts[0]
377:         if ($parts[0] -ne $parts[1]) { $mode = "$($parts[0])>$($parts[1])" }
378:         $map[$path] = $mode
379:     }
380:     return , $map
381: }
