383: # Revision fingerprint of the working tree (T2). tree_sha256 is the SHA-256 of a
384: # deterministic manifest:
385: #
386: #     base <full sha, or 'none' before the first commit>
387: #     <XY> <mode> <blob id | deleted | dir> <path>[<TAB><rename source>]
388: #
389: # one line per entry of `git status --porcelain=v1 -uall -z` (ignored files are not
390: # listed by git status, so they are outside the fingerprint by definition), sorted by
391: # path (ordinal), LF-joined with a trailing LF. The path is part of every line, so a
392: # rename changes the value even when the content does not. <mode> comes from
393: # Get-GitModeMap for tracked entries ('=' when git diff HEAD does not list the path,
394: # i.e. the worktree matches HEAD there); untracked entries get 'u' (mode not
395: # recorded). Entries under the
396: # collaboration directory are excluded: the consultation's own output must not move
397: # the fingerprint. A submodule or nested repository is recorded as 'dir' and not
398: # recursed. Every omission is spelled out in fingerprint_note. No git -> tree_sha256
399: # '' and fingerprint_note 'no git'. changed_files and dirty count the manifest
400: # entries, i.e. also without the collaboration directory.
401: # git status runs with --no-optional-locks, so computing a fingerprint never writes
402: # to the repository (not even an index refresh) - -DryRun stays write-free.
403: function Get-RevisionInfo {
404:     param([string]$Root, [string]$CollabRoot = '')
405:     $info = [pscustomobject]@{
406:         base_commit       = 'unknown'
407:         short_sha         = 'unknown'
408:         dirty             = $false
409:         reviewed_revision = 'unknown'
410:         tree_sha256       = ''
411:         changed_files     = 0
412:         fingerprint_note  = 'no git'
413:         manifest          = ''
414:     }
415:     $status = Invoke-GitCapture -Root $Root -GitArgs @('--no-optional-locks', 'status', '--porcelain=v1', '-uall', '-z')
416:     if (-not $status -or $status.ExitCode -ne 0) { return $info }
417: 
418:     $notes = New-Object System.Collections.Generic.List[string]
419:     $head = Get-GitOutput -Root $Root -GitArgs @('rev-parse', '--verify', '-q', 'HEAD')
420:     $base = 'none'
421:     if ($head) {
422:         $base = ([string]@($head)[0]).Trim()
423:         $info.base_commit = $base
424:         $short = Get-GitOutput -Root $Root -GitArgs @('rev-parse', '--short', 'HEAD')
425:         if ($short) { $info.short_sha = ([string]@($short)[0]).Trim() }
426:     } else {
427:         $notes.Add('no commits yet')
428:     }
429: 
430:     $collabRel = $null
431:     if ($CollabRoot) {
432:         $collabRel = Get-RepoRelativePath -Root $Root -Path $CollabRoot
433:         if ($null -eq $collabRel) { $notes.Add('collab dir outside the repository') }
434:         elseif ($collabRel -eq '') { $notes.Add('collab dir is the repository root: nothing excluded'); $collabRel = $null }
435:     }
436:     $cmp = if ($script:OnWindows) { [StringComparison]::OrdinalIgnoreCase } else { [StringComparison]::Ordinal }
437: 
438:     # Parse the NUL-separated entries: "XY <path>", and for a rename or copy the
439:     # source path follows as the next NUL-terminated field.
440:     $tokens = $script:Utf8NoBom.GetString($status.Bytes).Split([char]0)
441:     $entries = New-Object System.Collections.Generic.List[object]
442:     $excluded = 0
443:     $i = 0
444:     while ($i -lt $tokens.Length) {
445:         $tok = $tokens[$i]
446:         $i++
447:         if ($tok.Length -lt 4) { continue }
448:         $xy = $tok.Substring(0, 2)
449:         $path = $tok.Substring(3)
450:         $orig = $null
451:         if ($xy[0] -ceq 'R' -or $xy[0] -ceq 'C' -or $xy[1] -ceq 'R' -or $xy[1] -ceq 'C') {
452:             if ($i -lt $tokens.Length) { $orig = $tokens[$i]; $i++ }
453:         }
454:         if ($collabRel -and ($path.Equals($collabRel, $cmp) -or $path.StartsWith($collabRel + '/', $cmp))) {
455:             $excluded++
456:             continue
457:         }
458:         $entries.Add([pscustomobject]@{ XY = $xy; Path = $path; Orig = $orig; Blob = ''; Mode = 'u' })
459:     }
460: 
461:     $modeMap = New-PathMap
462:     if ($head) { $modeMap = Get-GitModeMap -Root $Root }
463:     else { $notes.Add('tracked file modes not recorded (no HEAD to compare with)') }
464:     foreach ($e in $entries) {
465:         if ($e.XY -eq '??' -or -not $head) { continue }
466:         if ($modeMap.ContainsKey($e.Path)) { $e.Mode = $modeMap[$e.Path] } else { $e.Mode = '=' }
467:     }
468: 
469:     $toHash = New-Object System.Collections.Generic.List[string]
470:     $dirs = 0
471:     foreach ($e in $entries) {
472:         $full = [IO.Path]::Combine($Root, $e.Path)
473:         if ([IO.Directory]::Exists($full)) { $e.Blob = 'dir'; $dirs++ }
474:         elseif ([IO.File]::Exists($full)) { $toHash.Add($e.Path) }
475:         else { $e.Blob = 'deleted' }
476:     }
477:     if ($toHash.Count -gt 0) {
478:         $ids = Get-GitBlobIds -Root $Root -Paths $toHash.ToArray()
479:         foreach ($e in $entries) {
480:             if ($e.Blob) { continue }
481:             $id = $null
482:             if ($ids.TryGetValue($e.Path, [ref]$id)) { $e.Blob = $id } else { $e.Blob = 'unreadable' }
483:         }
484:     }
485:     $unreadable = @($entries | Where-Object { $_.Blob -eq 'unreadable' }).Count
486: 
487:     $keys = New-Object System.Collections.Generic.List[string]
488:     $lines = New-Object System.Collections.Generic.List[string]
489:     foreach ($e in $entries) {
490:         $line = $e.XY + ' ' + $e.Mode + ' ' + $e.Blob + ' ' + (ConvertTo-ManifestPath $e.Path)
491:         if ($null -ne $e.Orig) { $line += "`t" + (ConvertTo-ManifestPath $e.Orig) }
492:         $keys.Add($e.Path + [char]0 + $line)
493:         $lines.Add($line)
494:     }
495:     $keyArr = $keys.ToArray()
496:     $lineArr = $lines.ToArray()
497:     [Array]::Sort($keyArr, $lineArr, [StringComparer]::Ordinal)
498:     $sb = New-Object System.Text.StringBuilder
499:     [void]$sb.Append("base $base`n")
500:     foreach ($l in $lineArr) { [void]$sb.Append($l + "`n") }
501:     $manifest = $sb.ToString()
502: 
503:     if ($collabRel) { $notes.Add("collab dir '$collabRel' excluded ($excluded entries)") }
504:     $notes.Add('ignored files excluded')
505:     $notes.Add('untracked file modes not recorded')
506:     if ($dirs -gt 0) { $notes.Add("submodules not recursed ($dirs directory entries)") }
507:     else { $notes.Add('submodules not recursed') }
508:     if ($unreadable -gt 0) { $notes.Add("$unreadable files unreadable") }
509: 
510:     $info.manifest = $manifest
511:     $info.tree_sha256 = Get-Sha256Hex -Bytes ($script:Utf8NoBom.GetBytes($manifest))
512:     $info.changed_files = $entries.Count
513:     $info.dirty = ($entries.Count -gt 0)
514:     $info.reviewed_revision = $info.short_sha
515:     if ($info.dirty) { $info.reviewed_revision = "$($info.short_sha) + uncommitted" }
516:     $info.fingerprint_note = ($notes.ToArray() -join '; ')
517:     return $info
518: }
