530: # Built artifacts to bind a review to: resolves each path (as given, relative to one
531: # of $Bases or absolute) to { path = as given; full = absolute path }. A missing
532: # artifact stops the run - the caller asked to bind the review to it, silently
533: # skipping it would defeat the binding. Hashing happens separately (under the task
534: # lock, and again after the run). Emits one object per artifact; collect with @(...).
535: function Resolve-ArtifactPaths {
536:     param([string[]]$Paths, [string[]]$Bases)
537:     foreach ($raw in @($Paths)) {
538:         if (-not $raw) { continue }
539:         $resolved = $null
540:         if ([IO.Path]::IsPathRooted($raw)) {
541:             if (Test-Path -LiteralPath $raw -PathType Leaf) { $resolved = $raw }
542:         } else {
543:             foreach ($b in $Bases) {
544:                 $candidate = Join-Path $b $raw
545:                 if (Test-Path -LiteralPath $candidate -PathType Leaf) { $resolved = $candidate; break }
546:             }
547:         }
548:         if (-not $resolved) {
549:             $looked = if ([IO.Path]::IsPathRooted($raw)) { $raw } else { (@($Bases) | Select-Object -Unique) -join ', ' }
550:             Stop-WithError "artifact '$raw' not found (looked in: $looked); a review cannot be bound to a missing artifact."
551:         }
552:         [pscustomobject]@{ path = $raw; full = (Resolve-Path -LiteralPath $resolved).Path }
553:     }
554: }
