590: # Next consult number n and handoff number NN. No number that anything on disk
591: # already names may be handed out again:
592: #   n  > the ledger's entry count and every entry's n, every finding's
593: #        source.consult, every reviewer_checks[].consult, and the n of a leftover
594: #        lock reservation;
595: #   NN > every handoff file "<NN>-..." (two OR MORE digits, so 100-... counts),
596: #        every finding id F<NN>-<k>, and the nn of a leftover lock reservation.
597: # Recovered is set when the leftover reservation's n has no ledger entry (a run that
598: # stopped before its commit point); the caller reports it.
599: function Get-NextNumbers {
600:     param($Consults, $Store, [string]$HandoffsDir, $Leftover)
601:     $ledgerNs = @{}
602:     $maxN = @($Consults).Count
603:     foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
604:         $v = 0
605:         if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v)) {
606:             $ledgerNs[$v] = $true
607:             if ($v -gt $maxN) { $maxN = $v }
608:         }
609:     }
610:     $maxNn = 0
611:     if ($HandoffsDir -and (Test-Path -LiteralPath $HandoffsDir)) {
612:         foreach ($file in @(Get-ChildItem -LiteralPath $HandoffsDir -File -ErrorAction SilentlyContinue)) {
613:             $v = 0
614:             if ($file.Name -match '^(\d{2,})-' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxNn) { $maxNn = $v }
615:         }
616:     }
617:     if ($Store) {
618:         foreach ($f in @($Store.findings | Where-Object { $null -ne $_ })) {
619:             $v = 0
620:             $src = Get-PropertyValue $f 'source' $null
621:             if ($src -and [int]::TryParse([string](Get-PropertyValue $src 'consult' ''), [ref]$v) -and $v -gt $maxN) { $maxN = $v }
622:             foreach ($rc in @(Get-PropertyValue $f 'reviewer_checks' @())) {
623:                 $v = 0
624:                 if ($rc -and [int]::TryParse([string](Get-PropertyValue $rc 'consult' ''), [ref]$v) -and $v -gt $maxN) { $maxN = $v }
625:             }
626:             $v = 0
627:             if ([string](Get-PropertyValue $f 'id' '') -match '^F(\d{2,})-\d+$' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxNn) { $maxNn = $v }
628:         }
629:     }
630:     $recovered = $false
631:     $recN = $null
632:     $recNn = ''
633:     if ($Leftover) {
634:         $v = 0
635:         if ([int]::TryParse([string](Get-PropertyValue $Leftover 'n' ''), [ref]$v) -and $v -gt 0) {
636:             $recN = $v
637:             if (-not $ledgerNs.ContainsKey($v)) { $recovered = $true }
638:             if ($v -gt $maxN) { $maxN = $v }
639:         }
640:         $w = 0
641:         $leftNn = [string](Get-PropertyValue $Leftover 'nn' '')
642:         if ($leftNn -and [int]::TryParse($leftNn, [ref]$w) -and $w -gt 0) {
643:             $recNn = $leftNn
644:             if ($w -gt $maxNn) { $maxNn = $w }
645:             if ($null -eq $recN) { $recovered = $true }
646:         }
647:     }
648:     return [pscustomobject]@{
649:         N           = $maxN + 1
650:         Nn          = ('{0:D2}' -f ($maxNn + 1))
651:         Recovered   = $recovered
652:         RecoveredN  = $recN
653:         RecoveredNn = $recNn
654:     }
655: }

48: # ----------------------------------------------------------------------------- text + JSON I/O
49: 
50: function Write-Utf8NoBom {
51:     param([string]$Path, [string]$Text)
52:     [IO.File]::WriteAllText($Path, $Text, $script:Utf8NoBom)
53: }
54: 
55: # Replaces $Path with $Text (UTF-8, no BOM) atomically: the text is written and
56: # flushed to a temp file in the same directory, which then replaces the destination
57: # in one step (Windows: File.Replace -> ReplaceFile; elsewhere: File.Move with
58: # overwrite -> rename(2)). A crash leaves either the old or the new file, never a
59: # truncated one (at worst a stray .<name>.<guid>.tmp next to it).
60: function Write-TextAtomic {
61:     param([string]$Path, [string]$Text)
62:     $full = [IO.Path]::GetFullPath($Path)
63:     $dir = [IO.Path]::GetDirectoryName($full)
64:     $tmp = Join-Path $dir ('.' + [IO.Path]::GetFileName($full) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
65:     $bytes = $script:Utf8NoBom.GetBytes($Text)
66:     $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
67:     try {
68:         $fs.Write($bytes, 0, $bytes.Length)
69:         $fs.Flush($true)
70:     } finally { $fs.Dispose() }
71:     $lastError = $null
72:     for ($attempt = 1; $attempt -le 8; $attempt++) {
73:         try {
74:             if (-not [IO.File]::Exists($full)) {
75:                 [IO.File]::Move($tmp, $full)
76:             } elseif ($script:OnWindows) {
77:                 # $null would reach .NET as '' - NullString is a real null (no backup file).
78:                 [IO.File]::Replace($tmp, $full, [System.Management.Automation.Language.NullString]::Value)
79:             } else {
80:                 [IO.File]::Move($tmp, $full, $true)
81:             }
82:             return
83:         } catch {
84:             # A reader holding the destination open without FileShare.Delete makes
85:             # ReplaceFile fail with a sharing violation; it is gone a moment later.
86:             $lastError = $_.Exception
87:             Start-Sleep -Milliseconds 250
88:         }
89:     }
90:     try { [IO.File]::Delete($tmp) } catch { }
91:     throw "could not replace '$full': $($lastError.Message)"
92: }
93: 
94: # JSON stores (sessions.json, findings.json): UTF-8 without BOM, LF line endings,
95: # replaced atomically. -InputObject, never the pipeline: piping an array into
96: # ConvertTo-Json unrolls it.
97: function Write-JsonFile {
98:     param([string]$Path, $Object)
99:     $json = ConvertTo-Json -InputObject $Object -Depth 20
100:     Write-TextAtomic -Path $Path -Text (($json -replace "`r`n", "`n") + "`n")
101: }
102: 
103: # Reads an existing JSON store. $null when the file does not exist. An EXISTING
104: # store that is empty, unreadable, unparseable or not a JSON object is corruption:
105: # refuse, never start over with a new store (that would silently drop history).
106: function Read-JsonStore {
107:     param([string]$Path)
108:     if (-not (Test-Path -LiteralPath $Path)) { return $null }
109:     $text = Read-SharedText -Path $Path
110:     $data = $null
111:     $why = ''
112:     if (-not $text.Trim()) {
113:         $why = 'it is empty or could not be read'
114:     } else {
115:         try { $data = ConvertFrom-Json -InputObject $text } catch { $why = "it does not parse: $(($_.Exception.Message -replace '\s+', ' ').Trim())" }
116:         if (-not $why -and -not ($data -is [System.Management.Automation.PSCustomObject])) { $why = 'it is not a JSON object' }
117:     }
118:     if ($why) {
119:         Stop-WithError "refusing to use '$Path': $why. An existing store is never replaced by a new one - restore it (e.g. from git) or move it aside deliberately, then retry."
120:     }
121:     return $data
122: }
123: 
124: # Start-Process holds the stdout/stderr redirection handles for a short while after
125: # the child exits, so a plain Get-Content can fail with "the process cannot access
126: # the file ... because it is being used by another process" - observed on a
127: # fast-failing codex run. Read with FileShare.ReadWrite (+ Delete, so an atomic
128: # replace of the file is not blocked by this reader) and retry briefly.
129: function Read-SharedText {
130:     param([string]$Path)
131:     if (-not (Test-Path -LiteralPath $Path)) { return '' }
132:     for ($attempt = 1; $attempt -le 6; $attempt++) {
133:         try {
134:             $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
135:             try {
136:                 $sr = New-Object System.IO.StreamReader($fs, (New-Object System.Text.UTF8Encoding($false)), $true)
137:                 try { return $sr.ReadToEnd() } finally { $sr.Dispose() }
138:             } finally { $fs.Dispose() }
139:         } catch {
140:             Start-Sleep -Milliseconds 250
141:         }
142:     }
143:     return ''
144: }
