1396: # ----------------------------------------------------------------------------- task lock
1397: 
1398: # Process start time as a UTC round-trip string. $null: no such process. '': the
1399: # process exists but its start time cannot be read (e.g. another user's process).
1400: function Get-ProcessStartIso {
1401:     param([int]$ProcessId)
1402:     $p = $null
1403:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
1404:     try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
1405: }
1406: 
1407: # A pid counts as alive when a process with that id exists and - if a start time was
1408: # recorded for it - still has that start time (otherwise the pid was reused).
1409: function Test-PidAlive {
1410:     param([int]$ProcessId, [string]$StartTime = '')
1411:     if ($ProcessId -le 0) { return $false }
1412:     $live = Get-ProcessStartIso -ProcessId $ProcessId
1413:     if ($null -eq $live) { return $false }
1414:     if ($StartTime -and $live -and $live -ne $StartTime) { return $false }
1415:     return $true
1416: }
1417: 
1418: function New-LockRefusal {
1419:     param([string]$Path, [string]$Message)
1420:     return [pscustomobject]@{ Acquired = $false; Path = $Path; Stream = $null; Nonce = ''; Record = $null; Leftover = $null; LeftoverText = ''; Message = $Message }
1421: }
1422: 
1423: # Content of a lock file without taking it (for messages and dry runs): the parsed
1424: # record, or $null when the file is absent, held exclusively, empty or unparseable.
1425: function Read-LockContent {
1426:     param([string]$Path)
1427:     if (-not [IO.File]::Exists($Path)) { return $null }
1428:     $text = ''
1429:     try {
1430:         $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
1431:         try {
1432:             $sr = New-Object System.IO.StreamReader($fs, $script:Utf8NoBom, $true)
1433:             $text = $sr.ReadToEnd()
1434:         } finally { $fs.Dispose() }
1435:     } catch { return $null }
1436:     if (-not $text.Trim()) { return $null }
1437:     $obj = $null
1438:     try { $obj = ConvertFrom-Json -InputObject $text } catch { return $null }
1439:     if (Test-IsJsonObject $obj) { return $obj }
1440:     return $null
1441: }
1442: 
1443: function Write-LockRecord {
1444:     param($Lock)
1445:     $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $Lock.Record -Compress -Depth 5) + "`n")
1446:     $fs = $Lock.Stream
1447:     $fs.SetLength(0)
1448:     $fs.Position = 0
1449:     $fs.Write($bytes, 0, $bytes.Length)
1450:     $fs.Flush($true)
1451: }
1452: 
1453: # One active consultation (or findings update) per task directory. Ownership is a
1454: # HELD HANDLE: <taskDir>/.consult.lock is opened with FileMode.OpenOrCreate and kept
1455: # open for the whole critical section, so the operating system - not a pid/start-time
1456: # heuristic - decides who holds it, and a holder that dies loses it automatically
1457: # (its handle is closed by the OS). The share mode excludes every other writer:
1458: #   * Windows: FileShare.Read - a refused contender can still read the holder's
1459: #     record for its message, but nobody else can open the file for writing;
1460: #   * elsewhere: FileShare.None - .NET on Unix emulates it with an advisory
1461: #     flock(LOCK_EX) (any other share mode maps to a shared lock, which would not
1462: #     exclude), so a refused contender cannot read the record there.
1463: # Cross-host exclusion (a task directory on a network share used from two machines)
1464: # is out of scope.
1465: #
1466: # The file content is the holder's record, and also the consultation's reservation:
1467: #   { pid, start_time, nonce, host, task, started, n, nn, reply, child_pid,
1468: #     child_start_time, survivors }
1469: # n, nn and reply are filled once allocated (before codex starts), child_pid once it
1470: # runs, survivors when a timeout kill could not stop the whole codex process tree.
1471: # A file we can open but that still holds a record is a LEFTOVER of a holder that
1472: # ended without a clean release: if any child_pid / survivor pid in it is alive on
1473: # this host, the lock is closed again untouched and the run refused; otherwise the
1474: # leftover is returned (Leftover / LeftoverText) so the caller can number past its
1475: # reservation, and our record replaces it.
1476: # Returns { Acquired; Path; Stream; Nonce; Record; Leftover; LeftoverText; Message }.
1477: function Enter-TaskLock {
1478:     param([string]$TaskDir, [string]$Task)
1479:     $path = Join-Path $TaskDir '.consult.lock'
1480:     $hostName = [Environment]::MachineName
1481:     $share = if ($script:OnWindows) { [IO.FileShare]::Read } else { [IO.FileShare]::None }
1482:     # Our record is ready before the open, so it replaces a leftover right away and a
1483:     # refused contender reading the file sees the live holder, not the previous one.
1484:     $nonce = [guid]::NewGuid().ToString()
1485:     $record = [pscustomobject]@{
1486:         pid              = $PID
1487:         start_time       = (Get-ProcessStartIso -ProcessId $PID)
1488:         nonce            = $nonce
1489:         host             = $hostName
1490:         task             = $Task
1491:         started          = (Get-IsoTimestamp)
1492:         n                = $null
1493:         nn               = ''
1494:         reply            = ''
1495:         child_pid        = $null
1496:         child_start_time = ''
1497:         survivors        = [object[]]@()
1498:     }
1499:     $fs = $null
1500:     try {
1501:         $fs = [IO.File]::Open($path, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, $share)
1502:     } catch [System.IO.IOException] {
1503:         # The holder may not have replaced a previous record yet: re-read briefly and
1504:         # name a pid only when that pid is alive.
1505:         $holder = $null
1506:         for ($attempt = 1; $attempt -le 8; $attempt++) {
1507:             $candidate = Read-LockContent -Path $path
1508:             $cpid = 0
1509:             if ($candidate -and [int]::TryParse([string](Get-PropertyValue $candidate 'pid' ''), [ref]$cpid) -and
1510:                 (Test-PidAlive -ProcessId $cpid -StartTime ([string](Get-PropertyValue $candidate 'start_time' '')))) { $holder = $candidate; break }
1511:             Start-Sleep -Milliseconds 125
1512:         }
1513:         $who = 'a live process'
1514:         if ($holder) {
1515:             $who = "pid $(Get-PropertyValue $holder 'pid' '?') on $(Get-PropertyValue $holder 'host' '?') since $(Get-PropertyValue $holder 'started' '?')"
1516:             $hn = Get-PropertyValue $holder 'n' $null
1517:             if ($null -ne $hn) { $who += " (consult n=$hn, handoff $(Get-PropertyValue $holder 'nn' '?'))" }
1518:         }
1519:         return (New-LockRefusal -Path $path -Message "another consultation for task '$Task' is running: $path is held open by $who. Wait for it to finish; the lock is released when that process exits.")
1520:     } catch {
1521:         return (New-LockRefusal -Path $path -Message "could not open the lock '$path': $($_.Exception.Message)")
1522:     }
1523: 
1524:     # We hold it. Read what a previous holder may have left behind, then put our
1525:     # record in its place at once.
1526:     $leftoverText = ''
1527:     try {
1528:         $len = [int]$fs.Length
1529:         if ($len -gt 0) {
1530:             $buf = New-Object byte[] $len
1531:             $fs.Position = 0
1532:             $read = 0
1533:             while ($read -lt $len) {
1534:                 $r = $fs.Read($buf, $read, $len - $read)
1535:                 if ($r -le 0) { break }
1536:                 $read += $r
1537:             }
1538:             $leftoverText = $script:Utf8NoBom.GetString($buf, 0, $read)
1539:         }
1540:     } catch { $leftoverText = '' }
1541:     $lock = [pscustomobject]@{ Acquired = $true; Path = $path; Stream = $fs; Nonce = $nonce; Record = $record; Leftover = $null; LeftoverText = $leftoverText; Message = '' }
1542:     try { Write-LockRecord -Lock $lock } catch {
1543:         $fs.Dispose()
1544:         return (New-LockRefusal -Path $path -Message "could not write the lock '$path': $($_.Exception.Message)")
1545:     }
1546: 
1547:     $leftover = $null
1548:     if ($leftoverText.Trim()) {
1549:         try { $leftover = ConvertFrom-Json -InputObject $leftoverText } catch { $leftover = $null }
1550:         if (-not (Test-IsJsonObject $leftover)) { $leftover = $null }
1551:     }
1552:     $lock.Leftover = $leftover
1553:     if ($leftover) {
1554:         $pids = New-Object System.Collections.Generic.List[object]
1555:         $childPid = 0
1556:         if ([int]::TryParse([string](Get-PropertyValue $leftover 'child_pid' ''), [ref]$childPid) -and $childPid -gt 0) {
1557:             $pids.Add([pscustomobject]@{ pid = $childPid; start = [string](Get-PropertyValue $leftover 'child_start_time' '') })
1558:         }
1559:         foreach ($s in @(Get-PropertyValue $leftover 'survivors' @())) {
1560:             $sp = 0
1561:             if ([int]::TryParse([string]$s, [ref]$sp) -and $sp -gt 0) { $pids.Add([pscustomobject]@{ pid = $sp; start = '' }) }
1562:         }
1563:         if ($pids.Count -gt 0) {
1564:             $leftHost = [string](Get-PropertyValue $leftover 'host' '')
1565:             $pidList = (@($pids | ForEach-Object { $_.pid }) -join ', ')
1566:             $what = "task '$(Get-PropertyValue $leftover 'task' $Task)', consult n=$(Get-PropertyValue $leftover 'n' '?'), since $(Get-PropertyValue $leftover 'started' '?')"
1567:             $refusal = ''
1568:             if ($leftHost -and -not $leftHost.Equals($hostName, [StringComparison]::OrdinalIgnoreCase)) {
1569:                 $refusal = "the lock '$path' was left by host $leftHost with codex process(es) pid $pidList ($what); they cannot be checked from this host. Delete $path only if you know they are dead."
1570:             } else {
1571:                 $alive = @($pids | Where-Object { Test-PidAlive -ProcessId $_.pid -StartTime $_.start } | ForEach-Object { $_.pid })
1572:                 if ($alive.Count -gt 0) {
1573:                     $refusal = "a previous consultation's codex process is still running (pid $($alive -join ', '); $what). Wait for it to exit or stop it, then retry; $path keeps that record until then."
1574:                 }
1575:             }
1576:             if ($refusal) {
1577:                 # Put the previous record back untouched and let go.
1578:                 Exit-TaskLock -Lock $lock -RestoreText $leftoverText
1579:                 return (New-LockRefusal -Path $path -Message $refusal)
1580:             }
1581:         }
1582:     }
1583:     return $lock
1584: }
1585: 
1586: # Rewrites the held lock's record with the given fields (n, nn, reply, child_pid,
1587: # child_start_time, survivors).
1588: function Update-TaskLock {
1589:     param($Lock, [hashtable]$Fields)
1590:     if ($null -eq $Lock -or -not $Lock.Acquired -or $null -eq $Lock.Stream) { return }
1591:     foreach ($k in $Fields.Keys) { $Lock.Record.$k = $Fields[$k] }
1592:     Write-LockRecord -Lock $Lock
1593: }
1594: 
1595: # Releases a held lock:
1596: #   default       truncate, then delete and close (Windows: close, then delete -
1597: #                 best effort; a contender that opened the file in between keeps it,
1598: #                 because it holds it without FileShare.Delete. Elsewhere: delete
1599: #                 while still holding the lock, then close, so a later contender
1600: #                 creates a fresh file instead of sharing an unlinked one);
1601: #   -Keep         close only and leave the record (survivors of a timeout kill:
1602: #                 the next run reads them and refuses while they live);
1603: #   -RestoreText  put a leftover reservation back and close (codex-findings.ps1
1604: #                 does not consume a reservation it found).
1605: function Exit-TaskLock {
1606:     param($Lock, [switch]$Keep, [string]$RestoreText = '')
1607:     if ($null -eq $Lock -or -not $Lock.Acquired -or $null -eq $Lock.Stream) { return }
1608:     $fs = $Lock.Stream
1609:     $Lock.Acquired = $false
1610:     try {
1611:         if ($Keep) { $fs.Dispose(); return }
1612:         if ($RestoreText) {
1613:             $bytes = $script:Utf8NoBom.GetBytes($RestoreText)
1614:             $fs.SetLength(0)
1615:             $fs.Position = 0
1616:             $fs.Write($bytes, 0, $bytes.Length)
1617:             $fs.Flush($true)
1618:             $fs.Dispose()
1619:             return
1620:         }
1621:         $fs.SetLength(0)
1622:         $fs.Flush($true)
1623:         if ($script:OnWindows) {
1624:             $fs.Dispose()
1625:             try { [IO.File]::Delete($Lock.Path) } catch { }
1626:         } else {
1627:             try { [IO.File]::Delete($Lock.Path) } catch { }
1628:             $fs.Dispose()
1629:         }
1630:     } catch {
1631:         try { $fs.Dispose() } catch { }
1632:     }
1633: }
1634: 
1635: # ----------------------------------------------------------------------------- processes
1636: 
1637: # Descendant pids of $RootId (Windows: CIM; elsewhere: pgrep -P). Best effort.
1638: function Get-DescendantPids {
1639:     param([int]$RootId)
1640:     $found = New-Object System.Collections.Generic.List[int]
1641:     $queue = New-Object System.Collections.Generic.Queue[int]
1642:     $queue.Enqueue($RootId)
1643:     $previous = $ErrorActionPreference
1644:     $ErrorActionPreference = 'Continue'
1645:     try {
1646:         $all = @()
1647:         if ($script:OnWindows) {
1648:             try { $all = @(Get-CimInstance -ClassName Win32_Process -Property ProcessId, ParentProcessId -ErrorAction Stop) } catch { $all = @() }
1649:         }
1650:         while ($queue.Count -gt 0) {
1651:             $cur = $queue.Dequeue()
1652:             $kids = @()
1653:             if ($script:OnWindows) {
1654:                 $kids = @($all | Where-Object { [int]$_.ParentProcessId -eq $cur -and [int]$_.ProcessId -ne $cur } | ForEach-Object { [int]$_.ProcessId })
1655:             } else {
1656:                 try { $kids = @(& pgrep -P $cur 2>$null) } catch { $kids = @() }
1657:             }
1658:             foreach ($k in $kids) {
1659:                 $n = 0
1660:                 if ([int]::TryParse(([string]$k).Trim(), [ref]$n) -and -not $found.Contains($n)) {
1661:                     $found.Add($n)
1662:                     $queue.Enqueue($n)
1663:                 }
1664:             }
1665:         }
1666:     } finally {
1667:         $ErrorActionPreference = $previous
1668:     }
1669:     return , ([int[]]$found.ToArray())
1670: }
1671: 
1672: # Kills the process AND its descendants (the launcher is usually a shim: cmd.exe or
1673: # node in front of the real codex binary). Windows: taskkill /T /F; elsewhere: the
1674: # pgrep -P tree. Best effort; returns the pids (root included) still alive after it,
1675: # as an [int[]] (empty when the whole tree is gone).
1676: function Stop-ProcessTree {
1677:     param($Process)
1678:     if ($null -eq $Process) { return , ([int[]]@()) }
1679:     $rootId = $Process.Id
1680:     $descendants = Get-DescendantPids -RootId $rootId
1681:     $previous = $ErrorActionPreference
1682:     $ErrorActionPreference = 'Continue'
1683:     try {
1684:         if ($script:OnWindows) {
1685:             try { & taskkill.exe /PID $rootId /T /F 2>$null | Out-Null } catch { }
1686:         }
1687:         foreach ($d in $descendants) {
1688:             try { Stop-Process -Id $d -Force -ErrorAction SilentlyContinue } catch { }
1689:         }
1690:         try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
1691:         try { $null = $Process.WaitForExit(10000) } catch { }
1692:     } finally {
1693:         $ErrorActionPreference = $previous
1694:     }
1695:     $alive = New-Object System.Collections.Generic.List[int]
1696:     $rootGone = $true
1697:     try { $rootGone = $Process.HasExited } catch { $rootGone = $true }
1698:     if (-not $rootGone) { $alive.Add($rootId) }
1699:     foreach ($d in $descendants) {
1700:         if (Get-Process -Id $d -ErrorAction SilentlyContinue) { $alive.Add($d) }
1701:     }
1702:     return , ([int[]]$alive.ToArray())
1703: }
