107: function Read-Ledger {
108:     $data = Read-JsonStore -Path $sessionsPath
109:     if ($null -eq $data -or -not $data.PSObject.Properties['codex'] -or -not $data.codex.PSObject.Properties['consults']) { return @() }
110:     return @($data.codex.consults | Where-Object { $_ })
111: }
112: 
113: # Consult numbers named by a finding's reviewer checks that have no ledger entry
114: # (a consultation that recorded checks and stopped before its ledger write).
115: function Get-OrphanCheckConsults {
116:     param($Finding, [hashtable]$LedgerNs)
117:     $out = New-Object System.Collections.Generic.List[int]
118:     foreach ($rc in @(Get-PropertyValue $Finding 'reviewer_checks' @())) {
119:         $v = 0
120:         if ($rc -and [int]::TryParse([string](Get-PropertyValue $rc 'consult' ''), [ref]$v) -and -not $LedgerNs.ContainsKey($v) -and -not $out.Contains($v)) { $out.Add($v) }
121:     }
122:     return , ([int[]]$out.ToArray())
123: }
124: 
125: function Get-FindingConsult {
126:     param($Finding)
127:     $src = Get-PropertyValue $Finding 'source' $null
128:     if (-not $src) { return $null }
129:     $v = 0
130:     if ([int]::TryParse([string](Get-PropertyValue $src 'consult' ''), [ref]$v)) { return $v }
131:     return $null
132: }
133: 
134: function ConvertTo-ComparablePath {
135:     param([string]$Path)
136:     return ($Path -replace '\\', '/').ToLowerInvariant()
137: }
138: 
139: # ----------------------------------------------------------------------------- -List
140: 
141: if ($List) {
142:     if (-not (Test-Path -LiteralPath $findingsPath)) {
143:         Write-Host "codex-findings: no findings recorded for task '$Task' ($findingsPath does not exist)."
144:         exit 0
145:     }
146:     $store = Read-FindingsFile -Path $findingsPath -Task $Task
147:     $ledger = @(Read-Ledger)
148:     # consult n -> reply path of its ledger entry
149:     $ledgerReplies = @{}
150:     foreach ($c in $ledger) {
151:         $v = 0
152:         if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v)) {
153:             $ledgerReplies[$v] = [string](Get-PropertyValue $c 'reply' '')
154:         }
155:     }
156:     $findings = @($store.findings)
157:     $ledgerNs = @{}
158:     foreach ($k in $ledgerReplies.Keys) { $ledgerNs[$k] = $true }
159:     $shown = 0
160:     $orphans = 0
161:     $orphanChecks = 0
162:     $byStatus = [ordered]@{}
163:     foreach ($s in $script:FindingStatuses) { $byStatus[$s] = 0 }
164:     $other = 0
165:     foreach ($f in $findings) {
166:         $st = [string](Get-PropertyValue $f 'status' '')
167:         if ($byStatus.Contains($st)) { $byStatus[$st] = $byStatus[$st] + 1 } else { $other++ }
168:         $n = Get-FindingConsult $f
169:         $srcReply = [string](Get-PropertyValue (Get-PropertyValue $f 'source' $null) 'reply' '')
170:         $orphan = $true
171:         if ($null -ne $n -and $ledgerReplies.ContainsKey($n)) {
172:             $ledgerReply = $ledgerReplies[$n]
173:             $orphan = ($srcReply -and $ledgerReply -and (ConvertTo-ComparablePath $srcReply) -ne (ConvertTo-ComparablePath $ledgerReply))
174:         }
175:         if ($orphan) { $orphans++ }
176:         $badChecks = Get-OrphanCheckConsults -Finding $f -LedgerNs $ledgerNs
177:         $orphanChecks += $badChecks.Count
178:         if (-not $All -and $script:OpenStatuses -notcontains $st -and $badChecks.Count -eq 0) { continue }
179:         $line = Format-FindingLine -Finding $f -Orphan:$orphan
180:         if ($badChecks.Count -gt 0) { $line += "  [ORPHAN reviewer check: consult $($badChecks -join ', ') has no ledger entry]" }
181:         Write-Host $line
182:         $shown++
183:     }
184:     $parts = @(foreach ($k in $byStatus.Keys) { "$k $($byStatus[$k])" })
185:     if ($other -gt 0) { $parts += "other $other" }
186:     $scope = if ($All) { 'all' } else { 'open only, plus any with an orphan check; -All for every finding' }
187:     Write-Host ""
188:     Write-Host "codex-findings: $shown shown ($scope); total $($findings.Count): $($parts -join ', '); orphans: $orphans finding(s), $orphanChecks reviewer check(s)."
189:     exit 0
190: }
191: 
245: # ----------------------------------------------------------------------------- -Id -Status
246: 
247: if (-not (Test-Path -LiteralPath $findingsPath)) {
248:     Stop-WithError "no findings recorded for task '$Task' ($findingsPath does not exist)."
249: }
250: 
251: $lock = Enter-TaskLock -TaskDir $taskDir -Task $Task
252: if (-not $lock.Acquired) { Stop-WithError $lock.Message }
253: # A reservation left by an interrupted consultation belongs to the next
254: # consultation's numbering: put it back on release instead of deleting it.
255: $restore = ''
256: if ($lock.Leftover -and ($null -ne (Get-PropertyValue $lock.Leftover 'n' $null) -or (Get-PropertyValue $lock.Leftover 'nn' ''))) { $restore = $lock.LeftoverText }
257: try {
258:     $store = Read-FindingsFile -Path $findingsPath -Task $Task
259:     $target = $null
260:     foreach ($f in @($store.findings)) {
261:         if ([string](Get-PropertyValue $f 'id' '') -eq $Id.Trim()) { $target = $f; break }
262:     }
263:     if (-not $target) {
264:         Stop-WithError "unknown finding id '$Id' in $findingsPath (codex-findings.ps1 -Task $Task -List -All shows every id)."
265:     }
266:     $current = [string](Get-PropertyValue $target 'status' '')
267:     if ($Status -eq 'proposed' -and $current -ne 'proposed' -and -not $Note.Trim()) {
268:         Stop-WithError "reopening $($target.id) ($current -> proposed) requires -Note (why it is open again)."
269:     }
270: 
271:     $rev = Get-RevisionInfo -Root $repoRoot -CollabRoot $collabRoot
272:     $record = [pscustomobject]@{
273:         when        = (Get-IsoTimestamp)
274:         status      = $Status
275:         by          = 'coordinator'
276:         note        = $Note.Trim()
277:         evidence    = $Evidence.Trim()
278:         base_commit = $rev.base_commit
279:         tree_sha256 = $rev.tree_sha256
280:     }
281:     Add-ArrayItem -Object $target -Name 'history' -Item $record
282:     if ($target.PSObject.Properties['status']) { $target.status = $Status }
283:     else { $target | Add-Member -NotePropertyName 'status' -NotePropertyValue $Status }
284:     Write-FindingsFile -Path $findingsPath -Store $store
285: 
286:     Write-Host "codex-findings: $($target.id) $current -> $Status (history: $(@($target.history).Count) records; tree sha256 $(if ($rev.tree_sha256) { $rev.tree_sha256.Substring(0, 12) } else { 'none (no git)' }))."
287:     Write-Host (Format-FindingLine -Finding $target)
288:     exit 0
289: } finally {
290:     Exit-TaskLock -Lock $lock -RestoreText $restore
291: }

